fn c14(vm: &mut Vm, inst: &mut Instance, depth: usize, mut r0: Value, mut r1: Value) -> Result<Value, FaultKind> {
    let mut r2 = Value::Nil;
    let mut r3 = Value::Nil;
    let mut r4 = Value::Nil;
    let mut r5 = Value::Nil;
    let mut pc: u32 = 0;
    loop {
        match pc {
            0 => {
                t!(vm, 14, 0, rt::tick(vm));
                r2 = Value::Int(t!(vm, 14, 1, t!(vm, 14, 1, rt::int(&r0)).checked_add(t!(vm, 14, 1, rt::int(&r1))).ok_or(FaultKind::Overflow)));
                t!(vm, 14, 1, rt::tick(vm));
                r3 = t!(vm, 14, 2, rt::load_state(vm, inst, 1));
                t!(vm, 14, 2, rt::tick(vm));
                r4 = Value::Int(t!(vm, 14, 3, t!(vm, 14, 3, rt::int(&r3)).checked_add(t!(vm, 14, 3, rt::int(&r2))).ok_or(FaultKind::Overflow)));
                t!(vm, 14, 3, rt::tick(vm));
                t!(vm, 14, 4, rt::store_state(vm, inst, 1, r4.clone()));
                t!(vm, 14, 4, rt::tick(vm));
                r5 = Value::Int(0);
                t!(vm, 14, 5, rt::tick(vm));
                return Ok(rt::ret(vm, inst, 14, std::mem::take(&mut r5)));
            }
            _ => return Err(rt::at(vm, 14, 0, FaultKind::Internal)),
        }
    }
}

fn s14(vm: &mut Vm, inst: &mut Instance, depth: usize, args: &[Value], caps: &[Value]) -> Result<Value, FaultKind> {
    c14(vm, inst, depth, args[0].clone(), caps[0].clone())
}
